static void user_font_get_data(uint32_t addr, void *buff, uint32_t size)
{
    lv_memcpy(buff, lvf_glyph_data + addr, size);
}

#define LVF_CHARS 4532
#define LVF_BASE_LINE 4
#define LVF_LINE_HEIGHT 18
#define LVF_BOX_W_MAX 16
#define LVF_BOX_H_MAX 15
#define LVF_BPP 1
#define LVF_UNICODE_MIN 32
#define LVF_UNICODE_MAX 32
#define LVF_OFS_UNICODE 64
#define LVF_OFS_GLYPH_DEC 9128
#define LVF_OFS_GLYPH_BITMAP 45384

